reference_solution:
def largest_mutated_number(num, change):
    digits = list(num)
    started = False
    for index, char in enumerate(digits):
        original = int(char)
        replacement = change[original]
        if replacement > original:
            started = True
            digits[index] = str(replacement)
        elif replacement == original and started:
            digits[index] = str(replacement)
        elif started:
            break
    return "".join(digits)

